        chargedTo = end;
      }
      let secretEnd = end;
      while (secretEnd < end + 2 && text[secretEnd] === "=") secretEnd++;
      found.push({ start: at, end: secretEnd, name });
    }
    from = Math.max(runEnd, at + 1);
  }
  return found;
}

